export type OrderStatus = 'PENDING' | 'PAID' | 'SHIPPED' | 'CANCELLED';

export class DomainError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'DomainError';
    Object.setPrototypeOf(this, DomainError.prototype);
  }
}

const CURRENCY_PATTERN = /^[A-Z]{3}$/;

/** Immutable Money value object; amount stored in minor units to avoid float drift. */
export class Money {
  private readonly _minor: number;
  private readonly _currency: string;

  constructor(amount: number, currency: string) {
    if (typeof amount !== 'number' || !Number.isFinite(amount)) {
      throw new DomainError('Money amount must be a finite number');
    }
    if (amount < 0) throw new DomainError('Money amount must not be negative');
    if (typeof currency !== 'string') throw new DomainError('Currency must be a string');
    const code = currency.trim().toUpperCase();
    if (!CURRENCY_PATTERN.test(code)) {
      throw new DomainError(`Invalid currency code: ${currency}`);
    }
    const minor = Math.round(amount * 100);
    if (!Number.isSafeInteger(minor)) throw new DomainError('Money amount out of range');
    this._minor = minor;
    this._currency = code;
    Object.freeze(this);
  }

  static of(amount: number, currency: string): Money {
    return new Money(amount, currency);
  }

  static zero(currency: string): Money {
    return new Money(0, currency);
  }

  get amount(): number {
    return Math.round(this._minor) / 100;
  }

  get currency(): string {
    return this._currency;
  }

  add(other: Money): Money {
    this.assertSameCurrency(other);
    return Money.fromMinor(this._minor + other._minor, this._currency);
  }

  subtract(other: Money): Money {
    this.assertSameCurrency(other);
    const result = this._minor - other._minor;
    if (result < 0) throw new DomainError('Money result must not be negative');
    return Money.fromMinor(result, this._currency);
  }

  multiply(factor: number): Money {
    if (typeof factor !== 'number' || !Number.isFinite(factor) || factor < 0) {
      throw new DomainError('Multiplication factor must be a non-negative finite number');
    }
    return Money.fromMinor(Math.round(this._minor * factor), this._currency);
  }

  equals(other: Money): boolean {
    return other instanceof Money && other._minor === this._minor && other._currency === this._currency;
  }

  isZero(): boolean {
    return this._minor === 0;
  }

  toString(): string {
    return `${this.amount.toFixed(2)} ${this._currency}`;
  }

  toJSON(): { amount: number; currency: string } {
    return { amount: this.amount, currency: this._currency };
  }

  private assertSameCurrency(other: Money): void {
    if (!(other instanceof Money)) throw new DomainError('Expected a Money instance');
    if (other._currency !== this._currency) {
      throw new DomainError(`Currency mismatch: ${this._currency} vs ${other._currency}`);
    }
  }

  private static fromMinor(minor: number, currency: string): Money {
    const money = Object.create(Money.prototype) as {
      _minor: number;
      _currency: string;
    };
    money._minor = minor;
    money._currency = currency;
    return Object.freeze(money) as unknown as Money;
  }
}

export interface OrderItem {
  id: string;
  quantity: number;
  price: Money;
}

export interface DomainEvent {
  type: string;
  orderId: string;
  occurredAt: Date;
  payload: Record<string, unknown>;
}

const TRANSITIONS: Record<OrderStatus, ReadonlyArray<OrderStatus>> = {
  PENDING: ['PAID', 'CANCELLED'],
  PAID: ['SHIPPED', 'CANCELLED'],
  SHIPPED: [],
  CANCELLED: [],
};

/** Order aggregate root: enforces invariants and guards state transitions. */
export class Order {
  private readonly _id: string;
  private readonly _customerId: string;
  private _status: OrderStatus = 'PENDING';
  private readonly _items = new Map<string, OrderItem>();
  private readonly _events: DomainEvent[] = [];

  constructor(id: string, customerId: string) {
    if (typeof id !== 'string' || id.trim() === '') throw new DomainError('Order id is required');
    if (typeof customerId !== 'string' || customerId.trim() === '') {
      throw new DomainError('Customer id is required');
    }
    this._id = id.trim();
    this._customerId = customerId.trim();
    this.record('OrderCreated', { customerId: this._customerId });
  }

  get id(): string {
    return this._id;
  }

  get customerId(): string {
    return this._customerId;
  }

  get status(): OrderStatus {
    return this._status;
  }

  get items(): ReadonlyArray<OrderItem> {
    return Array.from(this._items.values(), (item) => ({ ...item }));
  }

  get events(): ReadonlyArray<DomainEvent> {
    return this._events.map((event) => ({ ...event }));
  }

  addItem(productId: string, quantity: number, price: Money): void {
    if (this._status !== 'PENDING') {
      throw new DomainError(`Cannot modify items of a ${this._status} order`);
    }
    if (typeof productId !== 'string' || productId.trim() === '') {
      throw new DomainError('Product id is required');
    }
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new DomainError('Quantity must be a positive integer');
    }
    if (!(price instanceof Money)) throw new DomainError('Price must be a Money instance');
    if (price.isZero()) throw new DomainError('Price must be greater than zero');

    const key = productId.trim();
    const existing = this._items.get(key);
    if (existing) {
      if (!existing.price.equals(price)) {
        throw new DomainError(`Price conflict for item ${key}: ${existing.price} vs ${price}`);
      }
      this._items.set(key, { id: key, quantity: existing.quantity + quantity, price });
    } else {
      const first = this._items.values().next().value as OrderItem | undefined;
      if (first && first.price.currency !== price.currency) {
        throw new DomainError(`Order currency is ${first.price.currency}, received ${price.currency}`);
      }
      this._items.set(key, { id: key, quantity, price });
    }
    this.record('ItemAdded', { productId: key, quantity, price: price.toJSON() });
  }

  removeItem(productId: string): void {
    if (this._status !== 'PENDING') {
      throw new DomainError(`Cannot modify items of a ${this._status} order`);
    }
    if (!this._items.delete(productId)) {
      throw new DomainError(`Item not found: ${productId}`);
    }
    this.record('ItemRemoved', { productId });
  }

  pay(): void {
    if (this._items.size === 0) throw new DomainError('Cannot pay an order without items');
    this.transitionTo('PAID');
    this.record('OrderPaid', { total: this.getTotal().toJSON() });
  }

  ship(): void {
    this.transitionTo('SHIPPED');
    this.record('OrderShipped', {});
  }

  cancel(): void {
    this.transitionTo('CANCELLED');
    this.record('OrderCancelled', {});
  }

  getTotal(): Money {
    const items = Array.from(this._items.values());
    if (items.length === 0) return Money.zero('USD');
    return items.reduce<Money>(
      (sum, item) => sum.add(item.price.multiply(item.quantity)),
      Money.zero(items[0].price.currency),
    );
  }

  pullEvents(): DomainEvent[] {
    return this._events.splice(0, this._events.length);
  }

  private transitionTo(next: OrderStatus): void {
    if (!TRANSITIONS[this._status].includes(next)) {
      throw new DomainError(`Invalid transition ${this._status} -> ${next}`);
    }
    this._status = next;
  }

  private record(type: string, payload: Record<string, unknown>): void {
    this._events.push({ type, orderId: this._id, occurredAt: new Date(), payload });
  }
}

