/**
 * Order Bounded Context — Domain Layer (self-contained aggregate).
 *
 * Contains the `Money` value object, the `OrderItem` entity shape and the
 * `Order` aggregate root. All state transitions are guarded by explicit
 * invariants; no infrastructure concerns leak into this module.
 */

export type OrderStatus = 'PENDING' | 'PAID' | 'SHIPPED' | 'CANCELLED';

/** Base class for every violation of a domain invariant. */
export class DomainError extends Error {
  constructor(message: string) {
    super(message);
    this.name = new.target.name;
  }
}

export class InvalidMoneyError extends DomainError {}
export class CurrencyMismatchError extends DomainError {}
export class InvalidQuantityError extends DomainError {}
export class InvalidIdentifierError extends DomainError {}
export class InvalidStateTransitionError extends DomainError {}
export class EmptyOrderError extends DomainError {}

/** Currencies with two minor units; extend as the domain requires. */
const CURRENCY_PATTERN = /^[A-Z]{3}$/;
const MINOR_UNIT_FACTOR = 100;

/** Rounds to the currency minor unit to avoid IEEE-754 drift on sums. */
function toMinorUnits(amount: number): number {
  return Math.round(amount * MINOR_UNIT_FACTOR);
}

/**
 * Immutable value object representing a monetary amount in a single currency.
 * Equality is structural: same normalized amount and same currency code.
 */
export class Money {
  public readonly amount: number;
  public readonly currency: string;

  constructor(amount: number, currency: string) {
    if (typeof amount !== 'number' || !Number.isFinite(amount)) {
      throw new InvalidMoneyError(`Amount must be a finite number, got: ${String(amount)}`);
    }
    if (amount < 0) {
      throw new InvalidMoneyError(`Amount must not be negative, got: ${amount}`);
    }
    const normalizedCurrency = currency.trim().toUpperCase();
    if (!CURRENCY_PATTERN.test(normalizedCurrency)) {
      throw new InvalidMoneyError(`Currency must be a 3-letter ISO-4217 code, got: "${currency}"`);
    }
    this.amount = toMinorUnits(amount) / MINOR_UNIT_FACTOR;
    this.currency = normalizedCurrency;
    Object.freeze(this);
  }

  public static of(amount: number, currency: string): Money {
    return new Money(amount, currency);
  }

  public static zero(currency: string): Money {
    return new Money(0, currency);
  }

  public add(other: Money): Money {
    this.assertSameCurrency(other);
    return new Money(
      (toMinorUnits(this.amount) + toMinorUnits(other.amount)) / MINOR_UNIT_FACTOR,
      this.currency,
    );
  }

  public multiply(factor: number): Money {
    if (!Number.isInteger(factor) || factor < 0) {
      throw new InvalidMoneyError(`Factor must be a non-negative integer, got: ${factor}`);
    }
    return new Money((toMinorUnits(this.amount) * factor) / MINOR_UNIT_FACTOR, this.currency);
  }

  public equals(other: Money): boolean {
    return (
      other instanceof Money &&
      this.currency === other.currency &&
      toMinorUnits(this.amount) === toMinorUnits(other.amount)
    );
  }

  public toString(): string {
    return `${this.amount.toFixed(2)} ${this.currency}`;
  }

  private assertSameCurrency(other: Money): void {
    if (!(other instanceof Money)) {
      throw new InvalidMoneyError('Operand must be a Money instance.');
    }
    if (this.currency !== other.currency) {
      throw new CurrencyMismatchError(
        `Cannot combine ${this.currency} with ${other.currency}.`,
      );
    }
  }
}

/** Line item inside the Order aggregate. `id` references the product by ID only. */
export interface OrderItem {
  id: string;
  quantity: number;
  price: Money;
}

/** Allowed status transitions of the Order lifecycle. */
const TRANSITIONS: Readonly<Record<OrderStatus, ReadonlyArray<OrderStatus>>> = {
  PENDING: ['PAID', 'CANCELLED'],
  PAID: ['SHIPPED', 'CANCELLED'],
  SHIPPED: [],
  CANCELLED: [],
} as const;

function assertIdentifier(value: string, label: string): string {
  if (typeof value !== 'string' || value.trim().length === 0) {
    throw new InvalidIdentifierError(`${label} must be a non-empty string.`);
  }
  return value.trim();
}

/**
 * Order aggregate root. External code mutates line items exclusively through
 * this root, keeping the transactional consistency boundary intact.
 */
export class Order {
  public readonly id: string;
  public readonly customerId: string;

  private currentStatus: OrderStatus = 'PENDING';
  private readonly lineItems = new Map<string, OrderItem>();

  constructor(id: string, customerId: string) {
    this.id = assertIdentifier(id, 'Order id');
    this.customerId = assertIdentifier(customerId, 'Customer id');
  }

  public get status(): OrderStatus {
    return this.currentStatus;
  }

  /** Defensive copy: callers cannot mutate aggregate internals. */
  public get items(): ReadonlyArray<OrderItem> {
    return Array.from(this.lineItems.values(), (item) => ({ ...item }));
  }

  public addItem(productId: string, quantity: number, price: Money): void {
    const id = assertIdentifier(productId, 'Product id');
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new InvalidQuantityError(`Quantity must be a positive integer, got: ${quantity}`);
    }
    if (!(price instanceof Money)) {
      throw new InvalidMoneyError('Price must be a Money instance.');
    }
    this.assertMutable('add items to');
    const existing = this.lineItems.get(id);
    if (existing === undefined) {
      this.lineItems.set(id, { id, quantity, price });
      return;
    }
    if (!existing.price.equals(price)) {
      throw new CurrencyMismatchError(`Conflicting price for product "${id}".`);
    }
    this.lineItems.set(id, { id, quantity: existing.quantity + quantity, price });
  }

  public pay(): void {
    if (this.lineItems.size === 0) {
      throw new EmptyOrderError(`Order "${this.id}" has no items to pay for.`);
    }
    this.transitionTo('PAID');
  }

  public ship(): void {
    this.transitionTo('SHIPPED');
  }

  public cancel(): void {
    this.transitionTo('CANCELLED');
  }

  public getTotal(): Money {
    const items = Array.from(this.lineItems.values());
    const first = items[0];
    if (first === undefined) {
      throw new EmptyOrderError(`Order "${this.id}" has no items, total is undefined.`);
    }
    return items.reduce<Money>(
      (sum, item) => sum.add(item.price.multiply(item.quantity)),
      Money.zero(first.price.currency),
    );
  }

  private assertMutable(action: string): void {
    if (this.currentStatus !== 'PENDING') {
      throw new InvalidStateTransitionError(
        `Cannot ${action} order "${this.id}" while status is ${this.currentStatus}.`,
      );
    }
  }

  private transitionTo(next: OrderStatus): void {
    if (!TRANSITIONS[this.currentStatus].includes(next)) {
      throw new InvalidStateTransitionError(
        `Illegal transition ${this.currentStatus} -> ${next} for order "${this.id}".`,
      );
    }
    this.currentStatus = next;
  }
}
